#!/usr/bin/env node
// Generates the Claude Code and Codex plugins and their marketplace files from
// the hook table in src/runtime/host-hook-spec.ts, the same table the legacy
// `crosshead install claude-code|codex` writer uses.
//
//   node scripts/host-plugins.mjs          write the generated files
//   node scripts/host-plugins.mjs --check  fail if a checked-in file differs
//
// Uses the compiled spec in dist/ (run `npm run build` first). The plugins are
// thin: hooks, a setup skill and a launcher that runs the installed runtime.
// They never bundle, download or install runtime code.
import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";

const require = createRequire(import.meta.url);
const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), "..");

const json = (value) => `${JSON.stringify(value, null, 2)}\n`;

const author = { name: "FriendMachine", url: "https://crosshead.sh" };
const homepage = "https://crosshead.sh";
const repository = "https://github.com/FriendMachine/crosshead";
const description =
	"Persistent memory across coding agents. Hooks connect this host to the locally installed Crosshead runtime, shared with Claude Code, Codex, Hermes, OpenCode and Pi.";
const keywords = ["memory", "continuity", "hooks", "crosshead"];

const HOSTS = {
	"claude-code": {
		dir: "plugins/claude-code",
		label: "Claude Code",
		hookWrapper: "crosshead-claude-code-hook",
	},
	codex: {
		dir: "plugins/codex",
		label: "Codex",
		hookWrapper: "crosshead-codex-hook",
	},
};

const shQuote = (value) => `'${value.replaceAll("'", `'"'"'`)}'`;

// User-visible only: no additionalContext, so the model is not invited to run setup.
const noticeJson = (message) => JSON.stringify({ systemMessage: message });

const renderLauncher = (spec) => {
	const cases = Object.entries(HOSTS)
		.map(
			([host, info]) => `  ${host})
    hook=${info.hookWrapper}
    setup_notice=${shQuote(noticeJson(spec.pluginSetupHint(host)))}
    update_notice=${shQuote(noticeJson(spec.pluginUpdateHint(host)))}
    ;;`
		)
		.join("\n");
	return `#!/bin/sh
# Crosshead host plugin hook launcher. Generated by scripts/host-plugins.mjs from
# src/runtime/host-hook-spec.ts; do not edit.
#
# Runs the hook entrypoint of the Crosshead runtime installed by
# \`curl -fsSL https://crosshead.sh/install | bash\`. It never downloads or
# installs code. It only locates the runtime home (as the installer does); the
# runtime finds its own host configuration, including --claude-home and
# --codex-home installs. Without a usable runtime it prints a notice on
# SessionStart and exits 0 so the session is never blocked. POSIX sh only;
# Windows is not supported.
host="$1"
event="$2"
case "$host" in
${cases}
  *) exit 0 ;;
esac
conflict_notice=${shQuote(noticeJson(spec.PLUGIN_HOME_CONFLICT_HINT))}
notice() {
  cat > /dev/null 2>&1 || true
  if [ "$event" = SessionStart ]; then printf '%s\\n' "$1"; fi
  exit 0
}
# Empty variables count as unset, as in the installer and the runtime.
home="\${CROSSHEAD_HOME:-\${CROSSHEAD_RUNTIME_HOME:-\${ONLYBOTS_HOME:-\${ONLYBOTS_RUNTIME_HOME:-}}}}"
if [ -z "$home" ]; then
  if [ -e "$HOME/.crosshead" ] && [ -e "$HOME/.onlybots" ] && ! [ "$HOME/.crosshead" -ef "$HOME/.onlybots" ]; then
    notice "$conflict_notice"
  fi
  if [ ! -e "$HOME/.crosshead" ] && [ -e "$HOME/.onlybots" ]; then home="$HOME/.onlybots"; else home="$HOME/.crosshead"; fi
fi
wrapper="$home/bin/$hook"
[ -x "$wrapper" ] || notice "$setup_notice"
# A runtime that predates plugin dispatch would treat this call as an installer hook.
grep -q '${spec.PLUGIN_DISPATCH_CAPABILITY}' "$wrapper" 2> /dev/null || notice "$update_notice"
# The Codex hook wrapper sets CODEX_HOME to the configured home; keep the one Codex ran with.
if [ "$host" = codex ]; then
  CROSSHEAD_HOST_CODEX_HOME="\${CODEX_HOME:-$HOME/.codex}"
  export CROSSHEAD_HOST_CODEX_HOME
fi
exec "$wrapper" "$event" --home "$home" ${spec.PLUGIN_HOOK_VIA_FLAG.join(" ")} ${spec.PLUGIN_VERSION_FLAG} ${spec.CROSSHEAD_HOST_PLUGIN_VERSION}
`;
};

const renderSetupSkill = (host) => {
	const info = HOSTS[host];
	return `---
name: setup
description: Install or update the Crosshead runtime and connect it to ${info.label}. Run only when the user invokes it.
${host === "claude-code" ? "disable-model-invocation: true\n" : ""}---

# Set up Crosshead for ${info.label}

<!-- Generated by scripts/host-plugins.mjs; do not edit. -->

Crosshead shares one local runtime across projects and hosts. Start by asking
where the user wants automatic memory. Recommend the current project. Offer
additional directories, all projects, or manual commands only. Confirm the
profile for each directory; reuse an existing profile when the user selects
one. Explain that source excerpts can preserve exact workspace text and reach
the hosted service and later model prompts. Enable excerpts only on request.

1. Check \`crosshead --help\` and \`crosshead workspace list --json\`. If the CLI is
   missing or its help lacks \`--scope\`, explain the install and ask for explicit
   consent before running \`curl -fsSL https://crosshead.sh/install | bash\`.
   The installer verifies the downloaded release digest and installs the
   runtime. A new hosted profile uses a local key and authenticates to its
   selected service. When Crosshead is installed, reuse its runtime home.
2. Preview the user's selection. Replace the example profile name with the
   user's choice. Add \`--api-base https://crosshead.sh\` only if they want to
   create a new hosted profile.

   \`\`\`sh
   crosshead quickstart --scope project --adapter ${host} --workspace-root . --profile WORK --dry-run --json
   \`\`\`

   Use \`--scope all\` for user-wide hooks or \`--scope manual\` for manual use.
   Show the paths, profiles, source excerpt choices and any replaced hooks.
   Apply the confirmed command without \`--dry-run\`. For further directories
   with existing profiles, preview and apply \`crosshead workspace add\`.
3. Open a fresh session in the selected project${host === "codex"
  ? " and review the project’s hooks in \`/hooks\`" : ""}.
   Run \`crosshead workspace check --json\`. Report the configured profile and
   whether startup or resume has been observed. Check an unselected directory
   when the user chose project scope.

Use \`crosshead workspace remove\` to detach a project. Keep machine-specific
hook entries local. Use an explicit \`--profile\` for memory commands when
working outside a configured project.
`;
};

/** Map of repository-relative path to file contents. `spec` is host-hook-spec. */
export const renderHostPluginFiles = (spec) => {
	const version = spec.CROSSHEAD_HOST_PLUGIN_VERSION;
	const name = spec.CROSSHEAD_PLUGIN_NAME;
	const launcher = renderLauncher(spec);
	const files = {
		".claude-plugin/marketplace.json": json({
			name: spec.CROSSHEAD_MARKETPLACE_NAME,
			owner: author,
			metadata: { description: "Crosshead plugins for Claude Code. Codex reads .agents/plugins/marketplace.json." },
			plugins: [{ name, source: `./${HOSTS["claude-code"].dir}`, description, version }],
		}),
		".agents/plugins/marketplace.json": json({
			name: spec.CROSSHEAD_MARKETPLACE_NAME,
			interface: { displayName: "Crosshead" },
			plugins: [
				{
					name,
					source: { source: "local", path: `./${HOSTS.codex.dir}` },
					// Codex requires both policy fields on every entry; ON_INSTALL is the only
					// documented authentication value. The plugin itself asks for no credentials.
					policy: { installation: "AVAILABLE", authentication: "ON_INSTALL" },
					category: "Productivity",
				},
			],
		}),
		[`${HOSTS["claude-code"].dir}/.claude-plugin/plugin.json`]: json({
			name,
			displayName: "Crosshead",
			version,
			description,
			author,
			homepage,
			repository,
			license: "Apache-2.0",
			keywords,
		}),
		[`${HOSTS.codex.dir}/.codex-plugin/plugin.json`]: json({
			name,
			version,
			description,
			author,
			homepage,
			repository,
			license: "Apache-2.0",
			keywords,
			skills: "./skills/",
			hooks: "./hooks/hooks.json",
			interface: {
				displayName: "Crosshead",
				shortDescription: "Persistent memory shared across coding agents",
				developerName: "FriendMachine",
				category: "Productivity",
				capabilities: ["Read", "Write"],
				websiteURL: homepage,
			},
		}),
	};
	for (const host of Object.keys(HOSTS)) {
		const dir = HOSTS[host].dir;
		files[`${dir}/hooks/hooks.json`] = spec.renderPluginHooksFile(host);
		files[`${dir}/${spec.PLUGIN_HOOK_LAUNCHER}`] = launcher;
		files[`${dir}/skills/setup/SKILL.md`] = renderSetupSkill(host);
	}
	// Codex has no SKILL.md field for this; agents/openai.yaml keeps the setup
	// skill out of implicit (model-chosen) invocation. `$crosshead:setup` still works.
	files[`${HOSTS.codex.dir}/skills/setup/agents/openai.yaml`] = "policy:\n  allow_implicit_invocation: false\n";
	return files;
};

const isMain = process.argv[1] && path.resolve(process.argv[1]) === path.resolve(new URL(import.meta.url).pathname);
if (isMain) {
	const specPath = path.join(root, "dist", "runtime", "host-hook-spec.js");
	if (!existsSync(specPath)) {
		console.error("Missing dist/runtime/host-hook-spec.js; run npm run build first.");
		process.exit(1);
	}
	const spec = require(specPath);
	const files = renderHostPluginFiles(spec);
	const check = process.argv.includes("--check");
	const stale = [];
	for (const [relative, content] of Object.entries(files)) {
		const target = path.join(root, relative);
		const current = existsSync(target) ? readFileSync(target, "utf8") : null;
		if (current === content) continue;
		if (check) {
			stale.push(relative);
			continue;
		}
		mkdirSync(path.dirname(target), { recursive: true });
		writeFileSync(target, content);
		if (relative.endsWith(spec.PLUGIN_HOOK_LAUNCHER)) chmodSync(target, 0o755);
		console.log(`wrote ${relative}`);
	}
	if (stale.length > 0) {
		console.error(`Generated host plugin files are stale; run node scripts/host-plugins.mjs:\n${stale.join("\n")}`);
		process.exit(1);
	}
	if (check) console.log(`Host plugin files match the hook spec (${Object.keys(files).length} files).`);
}

